<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>{{ $exam->title }} — FRExam</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:Inter,sans-serif;color:#172033}*{box-sizing:border-box}body{margin:0;background:#f4f7fb;font-size:15px}.bar{position:sticky;top:0;z-index:2;background:#23395d;color:#fff;padding:16px max(20px,calc((100% - 1000px)/2));display:flex;justify-content:space-between;gap:16px}.wrap{max-width:1000px;margin:28px auto;padding:0 20px}.warning{background:#fff7ed;color:#9a3412;padding:12px 14px;border-radius:10px;border:1px solid #fed7aa}.question{background:#fffd;border-radius:16px;padding:24px;margin:18px 0;box-shadow:0 4px 14px #17203310}.number{color:#60718c;font-weight:800;font-size:12px;letter-spacing:.5px}.choice{display:block;padding:12px;margin-top:9px;border:1px solid #dbe3ee;border-radius:10px;cursor:pointer}.choice:has(input:checked){background:#e8eef7;border-color:#607da8}textarea{width:100%;min-height:100px;border:1px solid #cbd5e1;border-radius:10px;padding:12px;font:inherit}.button{border:0;border-radius:10px;padding:12px 17px;font:700 14px Inter;cursor:pointer}.save{background:#e8eef7;color:#23395d}.submit{background:#23395d;color:#fff;float:right}.flash{color:#166534}.lock{position:fixed;inset:0;z-index:30;display:grid;place-items:center;padding:20px;background:#172033df;color:#fff;text-align:center}.lock.hidden{display:none}.lock-card{width:min(100%,470px);padding:30px;border:1px solid #ffffff30;border-radius:22px;background:#23395d;box-shadow:0 22px 55px #0005}.lock h1{margin:12px 0 8px;font-size:23px}.lock p{margin:0;color:#e7effa;line-height:1.6}.lock button{margin-top:20px;border:0;border-radius:10px;background:#fff;color:#23395d;padding:12px 16px;font:800 14px Inter;cursor:pointer}.tab-alert{position:fixed;left:50%;bottom:22px;z-index:20;max-width:calc(100% - 32px);transform:translate(-50%,150%);padding:13px 16px;border-radius:12px;background:#9a3412;color:#fff;font-size:13px;font-weight:700;transition:.25s}.tab-alert.show{transform:translate(-50%,0)}@media(max-width:650px){.bar{padding:14px 16px}.wrap{margin:18px auto;padding:0 14px}.question{padding:19px}}</style></head><body><div class="lock" id="lock-screen"><section class="lock-card"><p style="font-size:42px;margin:0">🔒</p><h1>Mode ujian terkunci</h1><p>Aktifkan layar penuh untuk mulai mengerjakan. Berpindah tab atau keluar layar penuh akan dicatat untuk guru.</p><button id="lock-button" type="button">Aktifkan Layar Penuh & Mulai</button></section></div><div class="tab-alert" id="tab-alert" role="alert"></div><header class="bar"><span><strong>{{ $exam->title }}</strong><br><small>{{ $exam->subject }} · {{ $questions->count() }} soal</small></span><strong id="timer">Memuat waktu…</strong></header><main class="wrap">@if(session('saved'))<p class="flash">{{ session('saved') }}</p>@endif<p class="warning">🔒 Pilihan jawaban akan otomatis disimpan saat Anda menekan tombol kirim ujian.</p>@foreach($questions as $index=>$question)<article class="question" data-question="{{ $question->id }}"><p class="number">SOAL {{ $index+1 }} DARI {{ $questions->count() }}</p><p>{!! nl2br(e($question->question_text)) !!}</p>@php($choices=$question->choices?json_decode($question->choices,true):[]) @if(is_array($choices)&&count($choices))@foreach($choices as $key=>$choice)<label class="choice"><input type="radio" name="answer_{{ $question->id }}" value="{{ is_string($key)?$key:$choice }}" @checked((string)$answers->get($question->id)===(string)(is_string($key)?$key:$choice))> {{ is_string($choice)?$choice:'' }}</label>@endforeach @else<textarea class="essay" placeholder="Tulis jawaban Anda">{{ $answers->get($question->id) }}</textarea>@endif</article>@endforeach<form id="submit-exam" method="post" action="{{ route('student.submit',$attempt->id) }}" onsubmit="return confirm('Kirim semua jawaban dan akhiri ujian?')">@csrf<button class="button submit">Kirim Semua Jawaban & Selesai</button></form></main><script>const deadline=new Date(@json($deadline->toIso8601String())).getTime(),timer=document.querySelector('#timer'),activityUrl=@json(route('student.activity')),csrf=document.querySelector('meta[name=csrf-token]').content,attempt={{ $attempt->id }},lock=document.querySelector('#lock-screen'),lockButton=document.querySelector('#lock-button'),alertBox=document.querySelector('#tab-alert'),submitForm=document.querySelector('#submit-exam');let submitting=false,fullscreenActive=!!document.fullscreenElement;function report(event){fetch(activityUrl,{method:'POST',credentials:'same-origin',keepalive:true,headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({event:event,attempt_id:attempt})}).catch(()=>{})}function notice(message){alertBox.textContent=message;alertBox.classList.add('show');clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>alertBox.classList.remove('show'),6000)}async function unlock(){try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();fullscreenActive=!!document.fullscreenElement;if(fullscreenActive)lock.classList.add('hidden');else throw new Error()}catch(e){notice('Layar penuh wajib diaktifkan untuk melanjutkan ujian.')}}lockButton.onclick=unlock;function tick(){const s=Math.max(0,Math.ceil((deadline-Date.now())/1000));timer.textContent=`Sisa waktu: ${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;if(!s)submitForm.requestSubmit()}document.addEventListener('visibilitychange',()=>{if(document.hidden&&!submitting)report('tab_hidden')});document.addEventListener('fullscreenchange',()=>{const active=!!document.fullscreenElement;if(fullscreenActive&&!active&&!submitting){report('fullscreen_exit');lock.classList.remove('hidden');notice('Peringatan: Anda keluar dari layar penuh. Aktifkan kembali untuk melanjutkan.')}fullscreenActive=active});window.addEventListener('beforeunload',e=>{if(!submitting){report('page_exit');e.preventDefault();e.returnValue='Ujian masih berlangsung. Aktivitas keluar akan dicatat.'}});submitForm.addEventListener('submit',()=>{document.querySelectorAll('.question').forEach(card=>{const id=card.dataset.question,selected=card.querySelector('input[type=radio]:checked'),essay=card.querySelector('.essay'),answer=selected?selected.value:(essay?essay.value:'');const hidden=document.createElement('input');hidden.type='hidden';hidden.name=`answers[${id}]`;hidden.value=answer;submitForm.appendChild(hidden)});submitting=true;if(document.fullscreenElement)document.exitFullscreen().catch(()=>{})});tick();setInterval(tick,1000)</script></body></html>
